            MD_CHECK_CC( AddStartConfigRegister( 0x9888, 0x0c0c0b6e, REGISTER_TYPE_NOA ) );
            MD_CHECK_CC( AddStartConfigRegister( 0x9888, 0x0e0c0aec, REGISTER_TYPE_NOA ) );
            MD_CHECK_CC( AddStartConfigRegister( 0x9888, 0x100c0a6a, REGISTER_TYPE_NOA ) );
            MD_CHECK_CC( AddStartConfigRegister( 0x9888, 0x120c0028, REGISTER_TYPE_NOA ) );
