            MD_CHECK_CC( ( metric->SetDeltaReportReadEquation( "qw@0x150 2 qw@0x1b8 UMUL UADD 4 qw@0x1b0 UMUL UADD 8 qw@0x1a8 UMUL UADD 16 qw@0x1a0 UMUL UADD 32 qw@0x198 UMUL UADD 64 qw@0x190 UMUL UADD" ) ) );
            MD_CHECK_CC( ( metric->SetSnapshotReportDeltaFunction( "DELTA 32" ) ) );
